from b1_cards import card as _c, SEP, WP, IEP
C=[]
def card(*a,**k):
    import b1_cards as B; _c(*a,**k); C.append(B.C.pop())
# I · Greek beginnings
card("t-eironeia",1,"greek","εἰρωνεία","eirōneía","ay-roh-NAY-ah","dissembling, feigned ignorance","Socrates' opponents used eirōneia as an accusation: he pretended to know nothing so that others would commit themselves and he could pick their answers apart. Thrasymachus in the Republic calls it his 'usual' trick. The word gave us 'irony', and Kierkegaard wrote his dissertation on Socratic irony.","Socrates","Socrates",("Socratic irony",WP+"Socratic_irony"),("ὦ Ἡράκλεις, ἔφη, αὕτη 'κείνη ἡ εἰωθυῖα εἰρωνεία Σωκράτους","Heracles! he said. Here it is, that usual irony of Socrates.","Republic","1, 337a","rep.xml"),lang="grc")
card("t-mimesis",1,"greek","μίμησις","mímēsis","MEE-may-sis","imitation, representation","In Republic 10 Plato ranks the painter's bed below the carpenter's and the carpenter's below the Form of Bed: art copies a copy and stands 'third from the truth'. Aristotle answered in the Poetics that imitation is natural to humans and a way of learning. Theories of art as representation descend from this debate.","Plato","Plato",("Plato's aesthetics",SEP+"plato-aesthetics/"),("τὸν τοῦ τρίτου ἄρα γεννήματος ἀπὸ τῆς φύσεως μιμητὴν καλεῖς;","So you call the one whose product is third from nature an imitator?","Republic","10, 597e","rep.xml"),lang="grc")
card("t-idea-agathou",1,"greek","ἡ τοῦ ἀγαθοῦ ἰδέα","hē toû agathoû idéa","hay too ah-gah-THOO ee-DEH-ah","the Form of the Good","The highest object of knowledge in the Republic. Socrates will only describe it through the image of the sun: as the sun makes things visible and lets them grow, the Good makes the Forms knowable and gives them their being. Without it, he says, all other knowledge is of no benefit.","Plato","Plato",("Form of the Good",WP+"Form_of_the_Good"),("ἐπεὶ ὅτι γε ἡ τοῦ ἀγαθοῦ ἰδέα μέγιστον μάθημα, πολλάκις ἀκήκοας","You have often heard that the Form of the Good is the greatest thing to learn.","Republic","6, 505a","rep.xml"),lang="grc")
card("t-philosophos-basileus",1,"greek","φιλόσοφος βασιλεύς","philósophos basileús","fee-LOH-soh-foss bah-see-LEUS","philosopher-king","The 'biggest wave' of paradox in the Republic: there will be no end to the troubles of cities until philosophers rule or rulers become philosophers. Only those who know the Good can order a city well. Critics from Aristotle to Karl Popper have found the idea authoritarian.","Plato","Plato",("Philosopher king",WP+"Philosopher_king"),("ἐὰν μή, ἦν δ' ἐγώ, ἢ οἱ φιλόσοφοι βασιλεύσωσιν ἐν ταῖς πόλεσιν ἢ οἱ βασιλῆς τε νῦν λεγόμενοι καὶ δυνάσται φιλοσοφήσωσι γνησίως τε καὶ ἱκανῶς","Unless, I said, either philosophers become kings in the cities, or those now called kings and rulers genuinely and adequately do philosophy…","Republic","5, 473c–d","rep.xml"),lang="grc")
card("t-maieutike",1,"greek","μαιευτική","maieutikḗ","my-yoo-tee-KAY","the art of midwifery","In the Theaetetus Socrates, son of a midwife, says he practises the same art on souls: he is barren of wisdom himself but helps others give birth to their ideas, then tests whether the offspring is a phantom or genuine. 'Maieutic' became a name for teaching by questioning.","Socrates","Socrates",("Socratic method",WP+"Socratic_method"),("τῇ δέ γ' ἐμῇ τέχνῃ τῆς μαιεύσεως τὰ μὲν ἄλλα ὑπάρχει ὅσα ἐκείναις, διαφέρει δὲ τῷ τε ἄνδρας ἀλλὰ μὴ γυναῖκας μαιεύεσθαι","My art of midwifery has everything theirs has, but differs in that it delivers men, not women.","Theaetetus","150b","theaet.xml"),lang="grc")
card("t-homo-mensura",1,"greek","πάντων χρημάτων μέτρον ἄνθρωπος","pántōn chrēmátōn métron ánthrōpos","PAN-tone khray-MAH-tone MET-ron AN-throh-poss","man is the measure of all things","Protagoras' famous opening line, known mainly through Plato's Theaetetus, which reads it as relativism: things are for me as they appear to me, and for you as they appear to you. Socrates objects that if so, no one is wiser than anyone else, so why should anyone pay Protagoras to teach them?","Protagoras","Protagoras",("Protagoras",SEP+"protagoras/"),("φησὶ γάρ που πάντων χρημάτων μέτρον ἄνθρωπον εἶναι, τῶν μὲν ὄντων ὡς ἔστι, τῶν δὲ μὴ ὄντων ὡς οὐκ ἔστιν","For he says, I think, that a human being is the measure of all things: of things that are, that they are, and of things that are not, that they are not.","Theaetetus","152a","theaet.xml"),lang="grc")
card("t-dialektike",1,"greek","διαλεκτική","dialektikḗ","dee-ah-lek-tee-KAY","the art of discussion, dialectic","For Plato dialectic is the method of question and answer that rises from assumptions to first principles and finally to the Good itself. It is the coping-stone of the Republic's curriculum, studied only after years of mathematics. Aristotle used the word for arguing from accepted opinions, and Hegel for the movement of thought through contradiction.","Plato","Plato",("Dialectic",WP+"Dialectic"),("ὥσπερ θριγκὸς τοῖς μαθήμασιν ἡ διαλεκτικὴ ἡμῖν ἐπάνω κεῖσθαι","dialectic lies on top of our studies like a coping-stone.","Republic","7, 534e","rep.xml"),lang="grc")
# II · Aristotle & Hellenistic
card("t-prohairesis",2,"greek","προαίρεσις","prohaíresis","pro-HAI-reh-sis","deliberate choice","Aristotle's term for the choice that follows deliberation: a desire shaped by reasoning about what is in our power. Virtue is a disposition 'concerned with choice'. Epictetus later made prohairesis the one thing truly our own, the faculty that no tyrant can touch.","Aristotle","Aristotle",("Aristotle's ethics",SEP+"aristotle-ethics/"),("καὶ ἡ προαίρεσις ἂν εἴη βουλευτικὴ ὄρεξις τῶν ἐφ' ἡμῖν","Choice would be deliberative desire for things in our power.","Nicomachean Ethics","3.3, 1113a10","ne.xml"),lang="grc")
card("t-philia",2,"greek","φιλία","philía","fee-LEE-ah","friendship, love","Aristotle gives friendship two full books of the Nicomachean Ethics. He distinguishes friendships of utility, of pleasure and of character; only the last, between good people who love each other for who they are, is complete. Philia covers more than 'friendship': family love, civic concord, business partnership.","Aristotle","Aristotle",("Friendship",SEP+"friendship/"),("ἄνευ γὰρ φίλων οὐδεὶς ἕλοιτ' ἂν ζῆν, ἔχων τὰ λοιπὰ ἀγαθὰ πάντα","For without friends no one would choose to live, even if he had all the other goods.","Nicomachean Ethics","8.1, 1155a5","ne.xml"),lang="grc")
card("t-kinoun-akineton",2,"greek","κινοῦν ἀκίνητον","kinoûn akínēton","kee-NOON ah-KEE-nay-ton","unmoved mover","Motion has to start somewhere, so Aristotle argues for a first mover that moves without being moved. It cannot push, so it moves 'as something loved': the heavens turn in imitation of its perfection. It is pure thinking, thinking itself. Aquinas built his first way to God on this argument.","Aristotle","Aristotle",("Unmoved mover",WP+"Unmoved_mover"),("κινεῖ δὴ ὡς ἐρώμενον, κινούμενα δὲ τἆλλα κινεῖ","It moves as something loved, and the other things move by being moved.","Metaphysics","12.7, 1072b3","meta.xml"),lang="grc")
card("t-kosmopolites",2,"greek","κοσμοπολίτης","kosmopolítēs","koz-moh-poh-LEE-tace","citizen of the world","Diogenes the Cynic, an exile from Sinope who lived in a jar in Athens, refused to identify with any one city. The Stoics turned his quip into a doctrine: every rational being belongs to one community of gods and humans. Kant's idea of cosmopolitan right goes back to it.","Diogenes","Diogenes",("Cosmopolitanism",SEP+"cosmopolitanism/"),("ἐρωτηθεὶς πόθεν εἴη, κοσμοπολίτης, ἔφη","Asked where he came from, he said: 'I am a citizen of the world.'","Diogenes Laertius, Lives","6.63","dl.xml"),lang="grc")
card("t-adiaphora",2,"greek","ἀδιάφορα","adiáphora","ah-dee-AH-foh-rah","indifferent things","For the Stoics only virtue is good and only vice is bad; health, wealth, reputation and even life are 'indifferent'. Some indifferents are still 'preferred' and worth pursuing, but none makes a life happy or unhappy. Reformation theologians later reused the word for practices on which Christians could differ.","The Stoics","Epictetus",("Stoicism",SEP+"stoicism/"),("οὐδέτερα δὲ ὅσα μήτ' ὠφελεῖ μήτε βλάπτει, οἷον ζωή, ὑγίεια, ἡδονή, κάλλος, ἰσχύς, πλοῦτος, εὐδοξία, εὐγένεια","Neither good nor bad is whatever neither benefits nor harms, such as life, health, pleasure, beauty, strength, wealth, good reputation and noble birth.","Diogenes Laertius, Lives","7.102","dl.xml"),lang="grc")
card("t-prolepsis",2,"greek","πρόληψις","prólēpsis","PROH-layp-sis","preconception","A general notion formed naturally from repeated experience, such as our basic idea of a human or of the good. Epicureans and Stoics both counted it a criterion of truth: when we ask whether something is just, we already have a preconception of justice to test it against. Epictetus says education is learning to apply our natural preconceptions correctly.","The Stoics","Epictetus",("Stoic epistemology",IEP+"stoicism/"),("ἔστι δ' ἡ πρόληψις ἔννοια φυσικὴ τῶν καθόλου","A preconception is a natural notion of universals.","Diogenes Laertius, Lives","7.54","dl.xml"),lang="grc")
# III · Latin & Scholastic
card("t-ordo-amoris",3,"latin","ordo amoris","","OR-doh ah-MOH-ris","the order of love","For Augustine the problem is not that we love too much but that we love in the wrong order, preferring lesser goods to greater and creatures to God. Virtue is simply rightly ordered love. Max Scheler revived the phrase for a phenomenology of value.","Augustine","Augustine",("Augustine",SEP+"augustine/"),("Vnde mihi uidetur, quod definitio breuis et uera uirtutis ordo est amoris","So it seems to me that a brief and true definition of virtue is: the order of love.","City of God","15.22","civ15.html"),lang="la")
card("t-pondus-amor",3,"latin","pondus meum amor meus","","PON-doos MEH-oom AH-mor MEH-oos","my weight is my love","Augustine borrows ancient physics, where every body has a weight carrying it to its natural place: fire up, stone down. The soul's weight is its love, and it goes wherever its love carries it. Rest comes only when it reaches its proper place, in God.","Augustine","Augustine",("Augustine",SEP+"augustine/"),("pondus meum amor meus; eo feror, quocumque feror.","My weight is my love; by it I am carried wherever I am carried.","Confessions","13.9","conf13.html"),lang="la")
card("t-quinque-viae",3,"latin","quinque viae","","KWIN-kweh VEE-eye","the five ways","Aquinas' five short arguments that God exists, from motion, efficient causation, contingency, degrees of perfection and the order of nature. Each traces an observed feature of the world back to a first source 'which all call God'. They draw heavily on Aristotle and Avicenna.","Aquinas","Aquinas",("Five ways",WP+"Five_Ways_(Aquinas)"),("Respondeo dicendum quod Deum esse quinque viis probari potest.","I answer that the existence of God can be proved in five ways.","Summa Theologiae","I, q. 2, a. 3","sth1002.html"),lang="la")
card("t-lex-naturalis",3,"latin","lex naturalis","","leks nah-too-RAH-lis","natural law","For Aquinas the eternal law is God's plan for the universe. Rational creatures share in it actively, by grasping basic goods like life, knowledge and society and the precepts that follow from them; that share is natural law. Human laws are just only insofar as they derive from it.","Aquinas","Aquinas",("Natural law tradition in ethics",SEP+"natural-law-ethics/"),("Et talis participatio legis aeternae in rationali creatura lex naturalis dicitur.","And such participation of the eternal law in the rational creature is called natural law.","Summa Theologiae","I–II, q. 91, a. 2","sth2090.html"),lang="la")
# IV · Early modern
card("t-genius-malignus",4,"latin","genius malignus","","JEH-nee-oos mah-LIG-noos","evil demon","To push doubt as far as it can go, Descartes imagines a supremely powerful deceiver who uses all his skill to fool him, so that sky, earth and his own body may be illusions. Even then one thing survives: if I am deceived, I exist. Brain-in-a-vat scenarios are its modern descendants.","Descartes","Descartes",("Descartes' epistemology",SEP+"descartes-epistemology/"),("Supponam igitur non optimum Deum, fontem veritatis, sed genium aliquem malignum, eundemque summe potentem & callidum, omnem suam industriam in eo posuisse, ut me falleret","I will suppose, then, not that God, who is supremely good and the source of truth, but some malicious demon, supremely powerful and cunning, has used all his energies to deceive me.","Meditationes","I","desmed1.html"),lang="la")
card("t-coeur-raisons",4,"french","le cœur a ses raisons","","luh KUR ah say ray-ZOHN","the heart has its reasons","Pascal's heart is not mere feeling but a direct, intuitive knowledge: we know first principles, like the existence of space, by the heart, not by proof. Faith is 'God felt by the heart'. The line is often quoted about love, but Pascal meant it about religious knowledge.","Pascal","Pascal",("Blaise Pascal",SEP+"pascal/"),("Le cœur a ses raisons, que la raison ne connaît point.","The heart has its reasons, which reason does not know.","Pensées","277 (Brunschvicg)","pasc_all.txt"),lang="fr")
card("t-pari",4,"french","le pari","","luh pah-REE","the wager","Reason cannot settle whether God exists, Pascal says, but you must bet either way: 'you are embarked'. If you bet on God and win, you gain an infinite good; if you lose, you lose little. The argument is an early piece of decision theory, and critics ask which God one is meant to bet on.","Pascal","Pascal",("Pascal's wager",SEP+"pascal-wager/"),("Pesons le gain et la perte en prenant le parti de croire que Dieu est. Si vous gagnez, vous gagnez tout ; si vous perdez, vous ne perdez rien.","Let us weigh the gain and the loss in wagering that God exists. If you win, you win everything; if you lose, you lose nothing.","Pensées","233 (Brunschvicg)","pasc_all.txt"),lang="fr")
card("t-divertissement",4,"french","divertissement","","dee-vair-tees-MAHN","diversion","Why do people hunt, gamble and chase office? Not for the hare or the money, Pascal says, but to avoid thinking about their condition: mortal, weak and miserable. Diversion is our main consolation and our greatest misery, since it keeps us from facing ourselves.","Pascal","Pascal",("Blaise Pascal",SEP+"pascal/"),("tout le malheur des hommes vient de ne savoir pas se tenir en repos dans une chambre","all of humanity's unhappiness comes from not knowing how to stay quietly in a room.","Pensées","139 (Brunschvicg)","pasc_all.txt"),lang="fr")
card("t-affectus",4,"latin","affectus","","ahf-FEK-toos","affect, emotion","Spinoza treats emotions 'as if it were a question of lines, planes and bodies'. An affect is any change that increases or decreases the body's power of acting, together with the idea of that change. Joy is passage to greater power, sadness to less. When we adequately understand their causes, passions become actions.","Spinoza","Spinoza",("Spinoza's psychological theory",SEP+"spinoza-psychological/"),("Per affectum intelligo corporis affectiones quibus ipsius corporis agendi potentia augetur vel minuitur, juvatur vel coercetur et simul harum affectionum ideas.","By affect I understand affections of the body by which the body's power of acting is increased or diminished, aided or restrained, and at the same time the ideas of these affections.","Ethics","III, def. 3","spin3.html"),lang="la")
card("t-scientia-intuitiva",4,"latin","scientia intuitiva","","skee-EN-tee-ah in-too-ee-TEE-vah","intuitive knowledge","Spinoza's third and highest kind of knowledge, above opinion and reasoning. Where reason grasps general laws, intuition sees how each particular thing follows from God's nature, at a glance, as one sees the answer to a simple proportion. It gives rise to the intellectual love of God.","Spinoza","Spinoza",("Spinoza's theory of knowledge",SEP+"spinoza-epistemology-mind/"),("Præter hæc duo cognitionis genera datur, ut in sequentibus ostendam, aliud tertium quod scientiam intuitivam vocabimus.","Besides these two kinds of knowledge there is, as I will show, a third, which we will call intuitive knowledge.","Ethics","II, prop. 40, schol. 2","spin2.html"),lang="la")
# V · Kant
card("t-guter-wille",5,"german","guter Wille","","GOO-ter VIL-leh","good will","The Groundwork opens by saying that nothing can be called good without qualification except a good will. Intelligence, courage and even happiness can serve evil ends. A good will is good not for what it achieves but in itself, and its worth lies in acting from duty.","Kant","Kant",("Kant's moral philosophy",SEP+"kant-moral/"),("Es ist überall nichts in der Welt, ja überhaupt auch außer derselben zu denken möglich, was ohne Einschränkung für gut könnte gehalten werden, als allein ein guter Wille.","It is impossible to think of anything at all in the world, or indeed even beyond it, that could be considered good without limitation except a good will.","Grundlegung zur Metaphysik der Sitten","AA IV 393","kk_aa04_393.txt"))
card("t-autonomie",5,"german","Autonomie","","ow-toh-noh-MEE","self-legislation","For Kant the moral law is not imposed from outside, by God, society or desire, but given by reason to itself. A will governed by inclinations or rewards is heteronomous. Only an autonomous will is free, and that capacity is the source of human dignity.","Kant","Kant",("Kant's moral philosophy",SEP+"kant-moral/"),("Autonomie des Willens ist die Beschaffenheit des Willens, dadurch derselbe ihm selbst (unabhängig von aller Beschaffenheit der Gegenstände des Wollens) ein Gesetz ist.","Autonomy of the will is the property of the will by which it is a law to itself (independently of any property of the objects of willing).","Grundlegung zur Metaphysik der Sitten","AA IV 440","kk_aa04_440.txt"))
card("t-interesseloses-wohlgefallen",5,"german","interesseloses Wohlgefallen","","in-teh-REH-seh-loh-zes VOHL-geh-fal-len","disinterested pleasure","The first mark of a judgement of beauty: the pleasure does not depend on wanting the object to exist or be used. Pleasure in the agreeable serves appetite and pleasure in the good serves morality; pleasure in the beautiful is free. Because it rests on no private interest, I expect everyone to share it.","Kant","Kant",("Kant's aesthetics",SEP+"kant-aesthetics/"),("als eines Gegenstandes des Wohlgefallens ohne alles Interesse","as an object of satisfaction without any interest.","Kritik der Urtheilskraft","§ 6, AA V 211","kk_aa05_211.txt"))
card("t-genie",5,"german","Genie","","zheh-NEE","genius","Fine art cannot follow a rule laid down in advance, Kant argues, or it would be mere craft; yet it cannot be lawless. Genius is the inborn talent through which nature gives art its rule. Its works become models for others, but the genius cannot say how he produced them.","Kant","Kant",("Kant's aesthetics",SEP+"kant-aesthetics/"),("Genie ist das Talent (Naturgabe), welches der Kunst die Regel giebt.","Genius is the talent (natural gift) that gives the rule to art.","Kritik der Urtheilskraft","§ 46, AA V 307","kk_aa05_307.txt"))
card("t-bestirnter-himmel",5,"german","der bestirnte Himmel","","dair beh-SHTEERN-teh HIM-mel","the starry heavens","The conclusion of the second Critique sets two sources of awe side by side. The starry sky shows me as a speck in an immeasurable universe; the moral law reveals a worth independent of the whole world of sense. The words are carved on Kant's memorial plaque in Kaliningrad.","Kant","Kant",("Kant",SEP+"kant/"),("der bestirnte Himmel über mir und das moralische Gesetz in mir","the starry heavens above me and the moral law within me.","Kritik der praktischen Vernunft","Beschluss, AA V 161","kk_aa05_161.txt"))
card("t-krummes-holz",5,"german","krummes Holz","","KROOM-es HOLTS","crooked timber","Humans need a master to restrain them, Kant says, but every master is himself human. Perfect justice is therefore impossible; we can only approximate it. Isaiah Berlin took the line as the title of a book on the dangers of utopian politics.","Kant","Kant",("Kant's social and political philosophy",SEP+"kant-social-political/"),("aus so krummem Holze, als woraus der Mensch gemacht ist, kann nichts ganz Gerades gezimmert werden","out of timber as crooked as that from which man is made, nothing entirely straight can be built.","Idee zu einer allgemeinen Geschichte in weltbürgerlicher Absicht","Satz 6, AA VIII 23","kk_aa08_023.txt"))
card("t-transzendental",5,"german","transzendental","","trahns-tsen-den-TAHL","transcendental","Not to be confused with 'transcendent', which means beyond experience. Kant calls transcendental the inquiry into how knowledge of objects a priori is possible at all: the conditions in our own minds, such as space, time and the categories, that make experience possible.","Kant","Kant",("Kant's transcendental idealism",SEP+"kant-transcendental-idealism/"),("Ich nenne alle Erkenntnis transzendental, die sich nicht sowohl mit Gegenständen, sondern mit unserer Erkenntnisart von Gegenständen, insofern diese a priori möglich sein soll, überhaupt beschäftigt.","I call transcendental all knowledge that is concerned not so much with objects as with our way of knowing objects, insofar as this is to be possible a priori.","Kritik der reinen Vernunft","B25","g6343.txt"))
# VI · Hegel & idealism
card("t-eule-der-minerva",6,"german","Eule der Minerva","","OY-leh dair mee-NAIR-vah","the owl of Minerva","Philosophy always comes too late to tell the world how it ought to be, Hegel says. It understands an age only when that age has matured and begun to fade, just as Minerva's owl, the bird of wisdom, flies only at dusk. The line closes the preface to the Philosophy of Right.","Hegel","Hegel",("Hegel's social and political philosophy",SEP+"hegel-social-political/"),("die Eule der Minerva beginnt erst mit der einbrechenden Dämmerung ihren Flug","the owl of Minerva begins its flight only with the falling of dusk.","Grundlinien der Philosophie des Rechts","Vorrede","ia_grundlinienderph00hege.txt"))
card("t-vernuenftig-wirklich",6,"german","vernünftig / wirklich","","fair-NOONF-tikh / VIRK-likh","rational / actual","Hegel's 'double sentence' in the preface to the Philosophy of Right. Conservatives read it as blessing the Prussian state, radicals as a demand to make the world rational. Hegel later explained that 'actual' does not mean whatever happens to exist, but what fully realises its concept.","Hegel","Hegel",("Hegel",SEP+"hegel/"),("Was vernünftig ist, das ist wirklich; und was wirklich ist, das ist vernünftig.","What is rational is actual; and what is actual is rational.","Grundlinien der Philosophie des Rechts","Vorrede","ia_grundlinienderph00hege.txt"))
# VII · Nietzsche & Schopenhauer
card("t-langeweile",7,"german","Langeweile","","LAHNG-eh-vy-leh","boredom","For Schopenhauer life swings between two poles. While we want something we suffer from lack; as soon as we get it, the satisfaction drains away and boredom sets in. Pain and boredom are life's real ingredients, and the will that drives us can never be satisfied.","Schopenhauer","Schopenhauer",("Schopenhauer",SEP+"schopenhauer/"),("Sein Leben schwingt also, gleich einem Pendel, hin und her, zwischen dem Schmerz und der Langenweile","His life swings, then, like a pendulum, back and forth between pain and boredom.","Die Welt als Wille und Vorstellung","I, § 57","wwv4.txt"))
card("t-pathos-der-distanz",7,"german","Pathos der Distanz","","PAH-tos dair dis-TAHNTS","pathos of distance","Nietzsche's name for the feeling of rank that a noble caste has toward those beneath it. Out of this outward sense of difference, he argues, grew an inner one: the longing for ever higher, rarer and more comprehensive states of the soul. Every elevation of the type 'human' has needed it.","Nietzsche","Nietzsche",("Nietzsche's moral and political philosophy",SEP+"nietzsche-moral-political/"),("Ohne das Pathos der Distanz, wie es aus dem eingefleischten Unterschied der Stände … erwächst, könnte auch jenes andre geheimnissvollere Pathos gar nicht erwachsen","Without the pathos of distance, which grows out of the ingrained difference between ranks, that other, more mysterious pathos could not have grown either.","Jenseits von Gut und Böse","§ 257","g7204.txt"))
card("t-heerdenthier-moral",7,"german","Heerdenthier-Moral","","HAIRD-en-teer moh-RAHL","herd-animal morality","Nietzsche's charge against modern European morality: it values what is useful to the herd, such as gentleness, equality and the avoidance of risk, and calls anything exceptional dangerous. It claims to be the only morality there is. He insists it is just one type, and that higher moralities are possible.","Nietzsche","Nietzsche",("Nietzsche's moral and political philosophy",SEP+"nietzsche-moral-political/"),("Moral ist heute in Europa Heerdenthier-Moral","Morality in Europe today is herd-animal morality.","Jenseits von Gut und Böse","§ 202","g7204.txt"))
card("t-perspektivismus",7,"german","Perspektivismus","","per-spek-tee-VIS-moos","perspectivism","There is no view from nowhere, Nietzsche argues: all seeing and knowing is from some standpoint and serves some form of life. Denying this, as Plato did with his pure Good, is 'standing truth on its head'. Whether he meant that there are no facts at all is still debated.","Nietzsche","Nietzsche",("Nietzsche",SEP+"nietzsche/"),("das Perspektivische, die Grundbedingung alles Lebens","the perspectival, the basic condition of all life.","Jenseits von Gut und Böse","Vorrede","g7204.txt"))
# VIII · Phenomenology & existentialism
card("t-devenir-femme",8,"french","on ne naît pas femme","","ohn nuh NAY pah FAHM","one is not born a woman","The opening of the second volume of The Second Sex. No biological, psychological or economic fate defines what a woman is; femininity is produced by civilisation as a whole. The sentence became a founding text for the distinction later called sex and gender.","Simone de Beauvoir","Beauvoir",("Simone de Beauvoir",SEP+"beauvoir/"),("On ne naît pas femme : on le devient.","One is not born, but rather becomes, a woman.","Le Deuxième Sexe II","Part 1, ch. 1","fair_ia_deuxieme_sexe2.txt"),lang="fr")
# IX · Heidegger
card("t-gerede",9,"german","Gerede","","geh-RAY-deh","idle talk","Everyday talk that passes along what 'one' says without ever going back to the things themselves. It is not simply gossip: it lets everyone feel they have understood everything already, which closes off real questioning. With curiosity and ambiguity it marks Dasein's fallenness into das Man.","Heidegger","Heidegger",("Heidegger",SEP+"heidegger/"),("Das Gerede ist die Möglichkeit, alles zu verstehen ohne vorgängige Zueignung der Sache.","Idle talk is the possibility of understanding everything without first making the matter one's own.","Sein und Zeit","§ 35","fair_ia_sein_und_zeit.txt"))
# X · French thought
card("t-panoptisme",10,"french","panoptisme","","pah-nop-TEESM","panopticism","Bentham designed a prison where a central tower could watch every cell without being seen. For Foucault it is the diagram of modern disciplinary power: since inmates can never know whether they are watched, they watch themselves. The same logic runs through schools, hospitals, factories and barracks.","Foucault","Foucault",("Panopticon",WP+"Panopticon"),("Le Panoptique est une machine à dissocier le couple voir-être vu","The Panopticon is a machine for dissociating the pair seeing/being seen.","Surveiller et punir","III.3","fair_ia_surveiller_punir.txt"),lang="fr")
card("t-hyperreel",10,"french","hyperréel","","ee-pair-ray-EL","hyperreal","Baudrillard's word for a world in which models and images no longer copy a reality but generate one: 'a real without origin or reality'. Borges imagined a map as large as the empire; today, Baudrillard says, the map precedes the territory. Disneyland and reality television are among his examples.","Baudrillard","Baudrillard",("Jean Baudrillard",SEP+"baudrillard/"),("Elle est la génération par les modèles d'un réel sans origine ni réalité : hyperréel.","It is the generation by models of a real without origin or reality: a hyperreal.","Simulacres et simulation","La précession des simulacres","fair_ia_simulacres.txt"),lang="fr")
card("t-stade-du-miroir",10,"french","stade du miroir","","stahd dü meer-WAHR","mirror stage","Between about six and eighteen months, Lacan says, the infant recognises itself in a mirror with jubilation. It takes on a unified image of itself long before it can control its own body. The ego is born from this identification with an image, and is therefore from the start a kind of misrecognition.","Lacan","Lacan",("Mirror stage",WP+"Mirror_stage"),("Il y suffit de comprendre le stade du miroir comme une identification au sens plein que l'analyse donne à ce terme","It is enough to understand the mirror stage as an identification, in the full sense analysis gives the term.","Écrits","Le stade du miroir","fair_ia_ecrits.txt"),lang="fr")
card("t-mort-de-lhomme",10,"french","la mort de l'homme","","lah mor duh LOM","the death of man","Foucault argues that 'man', as an object of knowledge, is a recent invention, born around 1800 with biology, economics and philology. If the arrangement of knowledge that produced him shifts, he may disappear. The closing image of The Order of Things made the book a bestseller.","Foucault","Foucault",("Michel Foucault",SEP+"foucault/"),("alors on peut bien parier que l'homme s'effacerait, comme à la limite de la mer un visage de sable","then one can certainly wager that man would be erased, like a face drawn in sand at the edge of the sea.","Les Mots et les choses","ch. 10","fair_ia_mots_et_choses.txt"),lang="fr")
# XI · Wittgenstein & analytic
card("t-das-mystische",11,"analytic","das Mystische","","dahs MIS-tish-eh","the mystical","At the end of the Tractatus Wittgenstein says that ethics, the meaning of life and the fact that the world exists cannot be put into propositions. They are not nonsense in the dismissive sense: they show themselves. He told a publisher that the unwritten part of the book was the important one.","Wittgenstein","Wittgenstein",("Wittgenstein",SEP+"wittgenstein/"),("Es gibt allerdings Unaussprechliches. Dies zeigt sich, es ist das Mystische.","There is indeed the inexpressible. This shows itself; it is the mystical.","Tractatus Logico-Philosophicus","6.522","tlp.txt"))
card("t-tautologie",11,"analytic","Tautologie","","tow-toh-loh-GEE","tautology","A proposition true under every assignment of truth-values, like 'it is raining or it is not raining'. Wittgenstein argued that all logical truths are tautologies: they say nothing about the world but show its logical form. The Vienna Circle used the idea to explain how logic and mathematics can be certain without being about anything.","Wittgenstein","Wittgenstein",("Logical truth",SEP+"logical-truth/"),("Die Tautologie hat keine Wahrheitsbedingungen, denn sie ist bedingungslos wahr; und die Kontradiktion ist unter keiner Bedingung wahr.","A tautology has no truth-conditions, since it is unconditionally true; and a contradiction is true on no condition.","Tractatus Logico-Philosophicus","4.461","tlp.txt"))
card("t-bedeutung-gebrauch",11,"analytic","Bedeutung als Gebrauch","","beh-DOY-toong ahls geh-BROWKH","meaning as use","The later Wittgenstein's alternative to the idea that words get meaning by standing for objects. To understand a word, look at how it is used in the language-games where it lives. He hedges carefully: 'for a large class of cases', not all.","Wittgenstein","Wittgenstein",("Wittgenstein",SEP+"wittgenstein/"),("Die Bedeutung eines Wortes ist sein Gebrauch in der Sprache.","The meaning of a word is its use in the language.","Philosophische Untersuchungen","§ 43","pi.html"))
card("t-fliegenglas",11,"analytic","Fliegenglas","","FLEE-gen-glahs","fly-bottle","A fly-trap from which the fly cannot find the way out it came in by. For the later Wittgenstein philosophical problems are traps of this kind, produced by misunderstanding our own language. Philosophy should not build theories but show the way out, so that the problems disappear.","Wittgenstein","Wittgenstein",("Wittgenstein's metaphilosophy",SEP+"wittgenstein/#Met"),("Was ist dein Ziel in der Philosophie? – Der Fliege den Ausweg aus dem Fliegenglas zeigen.","What is your aim in philosophy? To show the fly the way out of the fly-bottle.","Philosophische Untersuchungen","§ 309","pi.html"))
card("t-kaefer",11,"analytic","Käfer in der Schachtel","","KAY-fer in dair SHAKH-tel","beetle in a box","Suppose everyone has a box with something in it called a 'beetle', and no one can look into anyone else's. Then the contents drop out of the language-game: the word would work the same if the box were empty. Wittgenstein's point is that sensation words cannot get their meaning from private inner objects.","Wittgenstein","Wittgenstein",("Private language",SEP+"private-language/"),("Angenommen, es hätte Jeder eine Schachtel, darin wäre etwas, was wir »Käfer« nennen. Niemand kann je in die Schachtel des Andern schaun","Suppose everyone had a box with something in it which we call a 'beetle'. No one can ever look into anyone else's box.","Philosophische Untersuchungen","§ 293","pi.html"))
card("t-regelfolgen",11,"analytic","einer Regel folgen","","EYE-ner RAY-gel FOL-gen","following a rule","Wittgenstein's pupil, told to 'add 2', writes 1000, 1004, 1008 and insists he is going on the same way. What makes 1002 the right step? No inner interpretation can settle it, since any interpretation can itself be variously applied. Wittgenstein's answer is that following a rule is a practice, a custom shared with others. Saul Kripke's 1982 reading made this a central debate.","Wittgenstein","Wittgenstein",("Rule-following",WP+"Wittgenstein_on_Rules_and_Private_Language"),("Einer Regel folgen, eine Mitteilung machen, einen Befehl geben, eine Schachpartie spielen sind Gepflogenheiten (Gebräuche, Institutionen).","Following a rule, making a report, giving an order, playing a game of chess are customs (uses, institutions).","Philosophische Untersuchungen","§ 199","pi.html"))
# XII · Eastern & Islamic
card("t-ziran",12,"eastern","自然","zìrán","dzuh-RAHN","so of itself, spontaneity","Literally 'self-so': what happens of its own accord, without force or design. In the Daodejing even the Dao models itself on ziran, so it is not a higher thing but the way things are when left alone. Modern Chinese uses the same word for 'nature'.","Laozi","Laozi",("Daoism",SEP+"daoism/"),("人法地，地法天，天法道，道法自然。","Humans follow earth, earth follows heaven, heaven follows the Dao, and the Dao follows what is so of itself.","Daodejing","25","ddjw.txt"),lang="zh")
card("t-yinyang",12,"eastern","陰陽","yīn yáng","yin yahng","shady and sunny, the two complementary forces","Originally the shady and sunny sides of a hill, yin and yang became the paired forces whose alternation runs through everything: dark and light, passive and active, cold and hot. Neither is good or bad; each turns into the other. The Daodejing describes the ten thousand things as carrying both.","Laozi","Laozi",("Yin and yang",WP+"Yin_and_yang"),("道生一，一生二，二生三，三生萬物。萬物負陰而抱陽，沖氣以為和。","The Dao gives birth to one, one to two, two to three, and three to the ten thousand things. The ten thousand things carry yin on their backs and embrace yang, blending their energies into harmony.","Daodejing","42","ddjw.txt"),lang="zh")
card("t-zhengming",12,"eastern","正名","zhèngmíng","jung-MING","rectifying names","Asked what he would do first in government, Confucius answers: make names correct. If a ruler is not acting as a ruler, or a father as a father, words and reality come apart, and then nothing can be done properly, from ritual to punishment. Xunzi later developed it into a theory of language.","Confucius","Confucius",("Confucius",SEP+"confucius/"),("名不正，則言不順；言不順，則事不成","If names are not correct, speech does not accord with things; if speech does not accord, affairs do not succeed.","Analects","13.3","lunyu13.txt"),lang="zh")
